// Failsafe: guarantee content becomes visible even if other scripts on the page
// fail to run (e.g. blocked/partial JS in some in-app browsers). Independent
// script tag so an error elsewhere can't prevent this fallback from firing.
(function(){
  function reveal(){
    try {
      var els = document.querySelectorAll('.reveal, .reveal-left, .reveal-right');
      for (var i=0;i<els.length;i++){ els[i].classList.add('in-view'); }
    } catch(e){}
  }
  setTimeout(reveal, 3000);
  if (document.readyState === 'complete') { setTimeout(reveal, 100); }
  else { window.addEventListener('load', function(){ setTimeout(reveal, 100); }); }
})();

// --- next script block ---

(function(){
  var grid = document.getElementById('serviceGrid');
  var prev = document.getElementById('serviceArrowPrev');
  var next = document.getElementById('serviceArrowNext');
  var dots = document.getElementById('serviceDots') ? document.getElementById('serviceDots').children : [];
  if(!grid) return;
  function cardWidth(){
    var card = grid.querySelector('.service-card');
    if(!card) return 0;
    var style = window.getComputedStyle(grid);
    var gap = parseFloat(style.columnGap || style.gap || 16);
    return card.getBoundingClientRect().width + gap;
  }
  function updateDots(){
    var idx = Math.round(grid.scrollLeft / cardWidth());
    for(var i=0;i<dots.length;i++){ dots[i].classList.toggle('active', i===idx); }
  }
  if(prev) prev.addEventListener('click', function(){ grid.scrollBy({left:-cardWidth(), behavior:'smooth'}); });
  if(next) next.addEventListener('click', function(){ grid.scrollBy({left:cardWidth(), behavior:'smooth'}); });
  grid.addEventListener('scroll', function(){ window.requestAnimationFrame(updateDots); }, {passive:true});

  // Auto-advance every 4s (mobile swipe view only)
  var autoTimer = null;
  var resumeTimer = null;
  function goToNext(){
    var w = cardWidth();
    if(!w) return;
    var atEnd = grid.scrollLeft + grid.clientWidth >= grid.scrollWidth - 5;
    grid.scrollTo({ left: atEnd ? 0 : grid.scrollLeft + w, behavior:'smooth' });
  }
  function startAuto(){
    stopAuto();
    autoTimer = setInterval(goToNext, 4000);
  }
  function stopAuto(){
    if(autoTimer){ clearInterval(autoTimer); autoTimer = null; }
  }
  function pauseThenResume(){
    stopAuto();
    if(resumeTimer) clearTimeout(resumeTimer);
    resumeTimer = setTimeout(startAuto, 4000);
  }
  ['pointerdown','touchstart'].forEach(function(evt){
    grid.addEventListener(evt, pauseThenResume, {passive:true});
  });
  if(prev) prev.addEventListener('click', pauseThenResume);
  if(next) next.addEventListener('click', pauseThenResume);
  startAuto();
})();

// --- next script block ---

(function(){
  var grid = document.getElementById('testiGrid');
  var prev = document.getElementById('testiArrowPrev');
  var next = document.getElementById('testiArrowNext');
  var dots = document.getElementById('testiDots') ? document.getElementById('testiDots').children : [];
  if(!grid) return;
  function cardWidth(){
    var card = grid.querySelector('.testi-card');
    if(!card) return 0;
    var style = window.getComputedStyle(grid);
    var gap = parseFloat(style.columnGap || style.gap || 20);
    return card.getBoundingClientRect().width + gap;
  }
  function activeIndex(){
    return Math.round(grid.scrollLeft / cardWidth());
  }
  function updateDots(){
    var idx = activeIndex();
    for(var i=0;i<dots.length;i++){ dots[i].classList.toggle('active', i===idx); }
  }
  function goTo(idx){
    var w = cardWidth();
    grid.scrollTo({ left: idx * w, behavior:'smooth' });
  }
  if(prev) prev.addEventListener('click', function(){ goTo(Math.max(0, activeIndex()-1)); });
  if(next) next.addEventListener('click', function(){ goTo(Math.min(grid.children.length-1, activeIndex()+1)); });
  grid.addEventListener('scroll', function(){ window.requestAnimationFrame(updateDots); }, {passive:true});

  var autoTimer = null;
  function goToNext(){
    var w = cardWidth();
    if(!w) return;
    var atEnd = grid.scrollLeft + grid.clientWidth >= grid.scrollWidth - 5;
    grid.scrollTo({ left: atEnd ? 0 : grid.scrollLeft + w, behavior:'smooth' });
  }
  var resumeTimer = null;
  function startAuto(){ stopAuto(); autoTimer = setInterval(goToNext, 4000); }
  function stopAuto(){ if(autoTimer){ clearInterval(autoTimer); autoTimer = null; } }
  function pauseThenResume(){
    stopAuto();
    if(resumeTimer) clearTimeout(resumeTimer);
    resumeTimer = setTimeout(startAuto, 4000);
  }
  ['pointerdown','touchstart'].forEach(function(evt){ grid.addEventListener(evt, pauseThenResume, {passive:true}); });
  if(prev) prev.addEventListener('click', pauseThenResume);
  if(next) next.addEventListener('click', pauseThenResume);
  startAuto();
})();

