document.addEventListener('DOMContentLoaded', function () {

  /* ---- header scroll state ---- */
  var header = document.getElementById('siteHeader');
  function onScroll(){ if (window.scrollY > 40) header.classList.add('scrolled'); else header.classList.remove('scrolled'); }
  window.addEventListener('scroll', onScroll); onScroll();

  /* ---- mobile nav (CSS-driven via #navCheck; JS only adds convenience closing) ---- */
  var navCheck = document.getElementById('navCheck');
  var navToggle = document.getElementById('navToggle');
  var mobileNav = document.getElementById('mobileNav');
  var mobileNavOverlay = document.getElementById('mobileNavOverlay');

  function closeMobileNav(){
    if (navCheck) navCheck.checked = false;
    mobileNav.classList.remove('open');
    mobileNavOverlay.classList.remove('open');
    if (navToggle) navToggle.classList.remove('active');
  }

  // keyboard accessibility: Enter/Space toggles the label like a button
  if (navToggle){
    navToggle.addEventListener('keydown', function(e){
      if (e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar'){
        e.preventDefault();
        if (navCheck) navCheck.checked = !navCheck.checked;
      }
    });
  }

  mobileNavOverlay.addEventListener('click', closeMobileNav);
  mobileNav.querySelectorAll('a').forEach(function(a){
    a.addEventListener('click', closeMobileNav);
  });
  if (navCheck){
    navCheck.addEventListener('change', function(){
      document.body.style.overflow = navCheck.checked ? 'hidden' : '';
    });
  }

  /* ---- dark mode toggle ---- */
  var themeToggle = document.getElementById('themeToggle');
  function readTheme(){ try { return localStorage.getItem('rootwell-theme'); } catch(e){ return null; } }
  function writeTheme(val){ try { localStorage.setItem('rootwell-theme', val); } catch(e){ /* storage unavailable (e.g. file:// on some mobile browsers) — ignore */ } }
  var savedTheme = readTheme();
  if (savedTheme === 'dark') document.documentElement.setAttribute('data-theme','dark');
  if (themeToggle){
    themeToggle.addEventListener('click', function(){
      var isDark = document.documentElement.getAttribute('data-theme') === 'dark';
      if (isDark){ document.documentElement.removeAttribute('data-theme'); writeTheme('light'); }
      else { document.documentElement.setAttribute('data-theme','dark'); writeTheme('dark'); }
    });
  }

  /* ---- scroll reveal ---- */
  var revealEls = document.querySelectorAll('.reveal, .reveal-left, .reveal-right');
  setTimeout(function(){ revealEls.forEach(function(el){ el.classList.add('in-view'); }); }, 2500);
  if ('IntersectionObserver' in window){
    var revealObs = new IntersectionObserver(function(entries, obs){
      entries.forEach(function(entry, i){
        if (entry.isIntersecting){
          setTimeout(function(){ entry.target.classList.add('in-view'); }, i * 50);
          obs.unobserve(entry.target);
        }
      });
    }, { threshold: 0.15 });
    revealEls.forEach(function(el){ revealObs.observe(el); });
  } else { revealEls.forEach(function(el){ el.classList.add('in-view'); }); }

  /* ---- image skeleton shimmer removal once each image finishes loading ---- */
  document.querySelectorAll('.img-wrap').forEach(function(w){ setTimeout(function(){ w.classList.add('loaded'); }, 2500); });
  document.querySelectorAll('.img-wrap img').forEach(function(img){
    function markLoaded(){ img.closest('.img-wrap').classList.add('loaded'); }
    if (img.complete && img.naturalWidth > 0) markLoaded();
    else { img.addEventListener('load', markLoaded); img.addEventListener('error', markLoaded); }
  });

  /* ---- number counters ---- */
  var counters = document.querySelectorAll('.stat-num[data-target]');
  if (counters.length && 'IntersectionObserver' in window){
    var counterObs = new IntersectionObserver(function(entries, obs){
      entries.forEach(function(entry){
        if (!entry.isIntersecting) return;
        var el = entry.target;
        var target = parseInt(el.getAttribute('data-target'), 10);
        var suffix = el.getAttribute('data-suffix') || '';
        var duration = 1400, start = null;
        function step(ts){
          if(!start) start = ts;
          var progress = Math.min((ts-start)/duration, 1);
          el.textContent = Math.floor(progress*target).toLocaleString() + suffix;
          if (progress < 1) requestAnimationFrame(step); else el.textContent = target.toLocaleString() + suffix;
        }
        requestAnimationFrame(step);
        obs.unobserve(el);
      });
    }, { threshold: 0.4 });
    counters.forEach(function(c){ counterObs.observe(c); });
  }

  /* ---- button ripple ---- */
  document.querySelectorAll('[data-ripple]').forEach(function(btn){
    btn.addEventListener('click', function(e){
      var rect = btn.getBoundingClientRect();
      var ripple = document.createElement('span');
      ripple.className = 'ripple';
      ripple.style.left = (e.clientX - rect.left) + 'px';
      ripple.style.top = (e.clientY - rect.top) + 'px';
      ripple.style.width = ripple.style.height = Math.max(rect.width, rect.height) + 'px';
      btn.appendChild(ripple);
      setTimeout(function(){ ripple.remove(); }, 650);
    });
  });

  /* ---- appointment form: goes straight to WhatsApp, with FormSubmit.co as a background record ---- */
  var FORM_ENDPOINT = 'https://formsubmit.co/ajax/kalpaahar.wellness@gmail.com';
  var CLINIC_WHATSAPP_NUMBER = '917757021501'; /* country code + number, no + or spaces */
  var form = document.getElementById('appointmentForm');
  var formStatus = form.querySelector('.form-status');
  var formBtn = form.querySelector('button[type="submit"]');

  /* ---- time slot picker: 30-minute slots (2 per hour), 10 AM–7 PM, Mon–Sat ---- */
  var BOOKINGS_KEY = 'kalpaahar_slot_bookings';
  function buildHalfHourSlots(startHour, endHour){
    var out = [];
    var fmt = function(h, m){
      var period = h >= 12 ? 'PM' : 'AM';
      var h12 = h % 12; if (h12 === 0) h12 = 12;
      return h12 + (m === 0 ? ':00' : ':30') + ' ' + period;
    };
    for (var h = startHour; h < endHour; h++){
      /* first half of the hour: HH:00 - HH:30 */
      var id1 = pad2(h) + '00-' + pad2(h) + '30';
      out.push({ id: id1, label: fmt(h,0) + ' – ' + fmt(h,30) });
      /* second half of the hour: HH:30 - (HH+1):00 */
      var nextH = h + 1;
      var id2 = pad2(h) + '30-' + pad2(nextH) + '00';
      out.push({ id: id2, label: fmt(h,30) + ' – ' + fmt(nextH,0) });
    }
    return out;
  }
  var SLOTS = buildHalfHourSlots(10, 19); /* 10:00 AM to 7:00 PM, 18 half-hour slots */
  var dateInput = document.getElementById('cf-date');
  var slotGrid = document.getElementById('slotGrid');
  var slotHidden = document.getElementById('cf-slot');
  var selectedSlotId = null;

  function pad2(n){ return n < 10 ? '0' + n : '' + n; }
  function toISODate(d){ return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()); }
  function formatDateLabel(d){
    var days = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
    var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    return days[d.getDay()] + ', ' + d.getDate() + ' ' + months[d.getMonth()];
  }
  function populateDateOptions(){
    if (!dateInput) return;
    var opts = '<option value="">Choose a date</option>';
    var d = new Date(); d.setHours(0,0,0,0);
    var added = 0, guard = 0;
    while (added < 14 && guard < 30){
      guard++;
      if (d.getDay() !== 0){ /* skip Sunday — clinic closed */
        opts += '<option value="' + toISODate(d) + '">' + formatDateLabel(d) + '</option>';
        added++;
      }
      d = new Date(d.getTime() + 86400000);
    }
    dateInput.innerHTML = opts;
  }
  populateDateOptions();

  function todayStr(){ return toISODate(new Date()); }

  function readBookings(){
    try{ return JSON.parse(localStorage.getItem(BOOKINGS_KEY)) || {}; }
    catch(e){ return {}; }
  }
  function writeBookings(data){
    try{ localStorage.setItem(BOOKINGS_KEY, JSON.stringify(data)); }catch(e){}
  }
  function isSlotPast(dateStr, slotId){
    var now = new Date();
    var todayIso = todayStr();
    if (dateStr !== todayIso) return false;
    var startPart = slotId.split('-')[0]; /* e.g. '1030' -> 10:30 */
    var startHour = parseInt(startPart.substring(0,2), 10);
    var startMinute = parseInt(startPart.substring(2,4), 10);
    var nowMinutes = now.getHours() * 60 + now.getMinutes();
    var slotStartMinutes = startHour * 60 + startMinute;
    return nowMinutes >= slotStartMinutes;
  }

  function renderSlots(){
    selectedSlotId = null;
    slotHidden.value = '';
    var dateStr = dateInput.value;
    dateInput.closest('.field').classList.remove('error');
    if (!dateStr){
      slotGrid.innerHTML = '<p class="slot-hint">Pick a date above to see available time slots.</p>';
      return;
    }
    var booked = readBookings()[dateStr] || [];
    var html = '';
    SLOTS.forEach(function(slot){
      var isBooked = booked.indexOf(slot.id) !== -1 || isSlotPast(dateStr, slot.id);
      var tag = isBooked ? 'Sold out' : 'Available';
      html += '<button type="button" class="slot-btn ' + (isBooked ? 'is-booked' : 'is-available') + '" data-slot="' + slot.id + '" ' + (isBooked ? 'disabled' : '') + '>' + slot.label + '<span class="slot-tag">' + tag + '</span></button>';
    });
    html += '<p class="slot-note">Grey / struck-through slots are already booked. Pick any highlighted slot.</p>';
    slotGrid.innerHTML = html;
  }

  if (dateInput){
    dateInput.addEventListener('change', renderSlots);
    dateInput.addEventListener('input', renderSlots);
  }

  if (slotGrid){
    slotGrid.addEventListener('click', function(e){
      var btn = e.target.closest('.slot-btn');
      if (!btn || btn.disabled) return;
      slotGrid.querySelectorAll('.slot-btn').forEach(function(b){ b.classList.remove('is-selected'); });
      btn.classList.add('is-selected');
      selectedSlotId = btn.getAttribute('data-slot');
      var slotDef = SLOTS.filter(function(s){ return s.id === selectedSlotId; })[0];
      slotHidden.value = dateInput.value + ' | ' + (slotDef ? slotDef.label : selectedSlotId);
      slotGrid.closest('.field').classList.remove('error');
    });
  }

  function commitSlotBooking(){
    if (!dateInput.value || !selectedSlotId) return;
    var data = readBookings();
    var dateStr = dateInput.value;
    if (!data[dateStr]) data[dateStr] = [];
    if (data[dateStr].indexOf(selectedSlotId) === -1){ data[dateStr].push(selectedSlotId); }
    writeBookings(data);
    renderSlots(); /* refresh grid so the just-booked slot now shows as sold out */
  }

  function buildWhatsAppMessage(){
    var get = function(id){ var el = document.getElementById(id); return el ? el.value.trim() : ''; };
    var heightUnit = document.getElementById('cf-height-unit').value;
    var weightUnit = document.getElementById('cf-weight-unit').value;
    var lines = [
      'Hi KalpAahar, I would like to book a consultation.',
      '',
      'Name: ' + get('cf-name'),
      'Age: ' + get('cf-age'),
      'Phone: ' + get('cf-phone'),
      'Height: ' + get('cf-height') + ' ' + heightUnit,
      'Weight: ' + get('cf-weight') + ' ' + weightUnit,
      'Email: ' + get('cf-email'),
      'Preferred Date & Time: ' + get('cf-slot'),
      'Primary Health Goal: ' + document.getElementById('cf-goal').value,
      'Message: ' + get('cf-message')
    ];
    return lines.join('\n');
  }

  form.addEventListener('submit', function(e){
    e.preventDefault();
    var valid = true;
    var name = document.getElementById('cf-name');
    var email = document.getElementById('cf-email');
    var phone = document.getElementById('cf-phone');
    var message = document.getElementById('cf-message');

    function setError(input, isError){ input.closest('.field').classList.toggle('error', isError); if (isError) valid = false; }

    setError(name, name.value.trim().length < 2);
    setError(email, !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim()));
    setError(phone, phone.value.replace(/\D/g,'').length < 7);
    // Message is optional — no validation applied

    var dateInvalid = !dateInput.value;
    dateInput.closest('.field').classList.toggle('error', dateInvalid);
    if (dateInvalid) valid = false;

    var slotInvalid = !selectedSlotId || !slotHidden.value;
    slotGrid.closest('.field').classList.toggle('error', slotInvalid);
    if (slotInvalid) valid = false;

    if (!valid){ return; }

    var originalBtnText = formBtn.textContent;
    formBtn.disabled = true;
    formBtn.textContent = 'Opening WhatsApp...';
    formStatus.style.display = 'block';
    formStatus.style.color = 'var(--ink-soft)';
    formStatus.textContent = 'Taking you to WhatsApp to confirm your booking...';

    /* Fire-and-forget background record — never blocks the WhatsApp redirect below */
    try{
      fetch(FORM_ENDPOINT, {
        method: 'POST',
        headers: { 'Accept': 'application/json' },
        body: new FormData(form)
      }).catch(function(){});
    } catch(err){ /* ignore */ }

    var waLink = 'https://wa.me/' + CLINIC_WHATSAPP_NUMBER + '?text=' + encodeURIComponent(buildWhatsAppMessage());
    window.open(waLink, '_blank', 'noopener');
    commitSlotBooking();

    formBtn.textContent = 'Sent — check WhatsApp';
    formStatus.style.color = 'var(--emerald)';
    formStatus.innerHTML = 'Your details are ready in WhatsApp — just hit send there to confirm your booking. Didn\'t open? <a href="' + waLink + '" target="_blank" rel="noopener" style="color:var(--emerald); font-weight:700; text-decoration:underline;">Tap here</a>.';

    setTimeout(function(){
      formBtn.disabled = false;
      formBtn.textContent = originalBtnText;
    }, 4000);
  });

  /* ---- newsletter: real submission via FormSubmit.co ---- */
  var newsletterForm = document.getElementById('newsletterForm');
  newsletterForm.addEventListener('submit', function(e){
    e.preventDefault();
    var emailInput = document.getElementById('newsletterEmail');
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(emailInput.value.trim())){
      emailInput.style.outline = '2px solid #e74c3c';
      return;
    }
    var originalHTML = newsletterForm.innerHTML;
    newsletterForm.innerHTML = '<p style="color:#fff; margin:0; font-weight:600;">Subscribing...</p>';

    var fd = new FormData();
    fd.append('Email', emailInput.value.trim());
    fd.append('_subject', 'New Newsletter Signup — KalpAahar Website');
    fd.append('_captcha', 'false');

    fetch(FORM_ENDPOINT, {
      method: 'POST',
      headers: { 'Accept': 'application/json' },
      body: fd
    })
    .then(function(res){ if(!res.ok) throw new Error('failed'); return res.json(); })
    .then(function(){
      newsletterForm.innerHTML = '<p style="color:#fff; margin:0; font-weight:600;">&#10003; Subscribed — welcome to the KalpAahar community!</p>';
    })
    .catch(function(){
      newsletterForm.innerHTML = originalHTML;
      var e2 = document.getElementById('newsletterEmail');
      if (e2) e2.style.outline = '2px solid #e74c3c';
    });
  });

});

