(function(){
  var overlays = {
    QuickConsult: document.getElementById('detailsOverlayQuickConsult'),
    ConditionPlan: document.getElementById('detailsOverlayConditionPlan'),
    GuidedProgram: document.getElementById('detailsOverlayGuidedProgram')
  };
  Object.keys(overlays).forEach(function(key){
    var overlay = overlays[key];
    if (!overlay) return;
    window['openDetails' + key] = function(){
      overlay.classList.add('open');
      document.body.style.overflow = 'hidden';
    };
    window['closeDetails' + key] = function(){
      overlay.classList.remove('open');
      document.body.style.overflow = '';
    };
    overlay.addEventListener('click', function(e){ if (e.target === overlay) window['closeDetails' + key](); });
  });
})();

