/* ============ EBOOK DETAILS MODAL — POWER LUNCH ============ */
(function(){
  var overlay = document.getElementById('detailsOverlayPowerLunch');
  var cover = document.getElementById('detCoverPowerLunch');
  var buyBtn = document.getElementById('detBuyNowBtnPowerLunch');

  window.openDetailsPowerLunch = function(triggerEl){
    var card = triggerEl.closest('.ebook-card');
    var img = card ? card.querySelector('.ebook-cover img') : null;
    if (img) cover.src = img.src;

    buyBtn.onclick = function(e){
      e.preventDefault();
      closeDetailsPowerLunch();
      openCheckout('Power Lunch', '299');
    };

    overlay.classList.add('open');
    document.body.style.overflow = 'hidden';
  };

  window.closeDetailsPowerLunch = function(){
    overlay.classList.remove('open');
    document.body.style.overflow = '';
  };

  overlay.addEventListener('click', function(e){ if (e.target === overlay) closeDetailsPowerLunch(); });
})();

