/* ============ EBOOK CHECKOUT MODAL ============ */
(function () {

  /* Point this at your deployed backend */
var CHECKOUT_API_BASE = "https://kalpaahar-payment.afk-mayuri.workers.dev";

var CHECKOUT_ENDPOINT = "https://formsubmit.co/ajax/kalpaahar.wellness@gmail.com";

  /* Must match the ids used in backend/ebooks/catalog.js */
  function slugifyTitle(title) {
    return (title || '')
      .toLowerCase()
      .replace(/,/g, '')
      .trim()
      .replace(/\s+/g, '-');
  }
  function getEbookId(title) {
    return slugifyTitle(title);
  }
  var overlay = document.getElementById('checkoutOverlay');
  var stepDetails = document.getElementById('coStepDetails');
  var stepPayment = document.getElementById('coStepPayment');
  var stepSuccess = document.getElementById('coStepSuccess');
  var detailsForm = document.getElementById('checkoutDetailsForm');
  var detailsStatus = document.getElementById('coDetailsStatus');
  var payStatus = document.getElementById('coPayStatus');
  var currentTitle = '', currentPrice = '';
  var currentEbookId = '';
  var currentCustomer = { name: '', email: '', phone: '' };

  function showStep(step){
    [stepDetails, stepPayment, stepSuccess].forEach(function(s){ s.classList.remove('active'); });
    step.classList.add('active');
  }

window.selectCollection = function(title, price){
  window.openCheckout(title, price);
};
  window.openCheckout = function(title, price){
    currentTitle = title || 'High Protein Breakfast';
    currentPrice = price || '299';
    currentEbookId = getEbookId(currentTitle);
    document.getElementById('coTitle').textContent = currentTitle;
    document.getElementById('coPrice').textContent = currentPrice;
    document.getElementById('coPayTitle').textContent = currentTitle;
    document.getElementById('coPayAmount').textContent = currentPrice;
    document.getElementById('coPayBtnAmount').textContent = currentPrice;
    document.getElementById('coSuccessTitle').textContent = currentTitle;

    detailsForm.reset();
    detailsForm.querySelectorAll('.co-field').forEach(function(f){ f.classList.remove('error'); });
    detailsStatus.style.display = 'none';
    payStatus.style.display = 'none';
    showStep(stepDetails);

    overlay.classList.add('open');
    document.body.style.overflow = 'hidden';
  };

  window.closeCheckout = function(){
    overlay.classList.remove('open');
    document.body.style.overflow = '';
  };

  overlay.addEventListener('click', function(e){ if (e.target === overlay) closeCheckout(); });

  detailsForm.addEventListener('submit', function(e){
    e.preventDefault();
    var name = document.getElementById('co-name');
    var email = document.getElementById('co-email');
    var phone = document.getElementById('co-phone');
    var consent = document.getElementById('co-consent');
    var valid = true;

    function setError(input, isError){ input.closest('.co-field').classList.toggle('error', isError); if (isError) valid = false; }
    setError(name, name.value.trim().length < 2);
    setError(email, !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim()));
    setError(phone, phone.value.replace(/\D/g,'').length < 7);

    if (!consent.checked){
      valid = false;
      detailsStatus.style.display = 'block';
      detailsStatus.style.color = '#c0392b';
      detailsStatus.textContent = 'Please agree to receive your eBook and health tips to continue.';
    }
    if (!valid) return;

    detailsStatus.style.display = 'none';
    document.getElementById('coPayEmail').textContent = email.value.trim();

    currentCustomer = {
      name: name.value.trim(),
      email: email.value.trim(),
      phone: phone.value.trim()
    };

    /* Fire-and-forget notification to the team so the order is on record before payment */
    try{
      var fd = new FormData();
      fd.append('Full Name', name.value.trim());
      fd.append('Email', email.value.trim());
      fd.append('Phone', phone.value.trim());
      fd.append('City', document.getElementById('co-city').value.trim());
      fd.append('eBook', currentTitle);
      fd.append('_subject', 'New eBook Order — ' + currentTitle);
      fd.append('_captcha', 'false');
      fetch(CHECKOUT_ENDPOINT, { method:'POST', headers:{ 'Accept':'application/json' }, body: fd }).catch(function(){});
    } catch(err){ /* ignore — never block checkout on the notification */ }

    /* Free items (price '0') skip Razorpay entirely and deliver right away */
    if (currentPrice === '0'){
      onPaymentDelivered();
    } else {
      payNow();
    }
  });

  function showPayError(message){
    payStatus.style.display = 'block';
    payStatus.style.color = '#c0392b';
    payStatus.textContent = message;
  }

  function showPayStatus(message){
    payStatus.style.display = 'block';
    payStatus.style.color = 'var(--ink-soft)';
    payStatus.textContent = message;
  }

  function setPayButtonDisabled(disabled){
    var btn = document.querySelector('#coStepPayment button[onclick="payNow()"]');
    if (btn){
      btn.disabled = disabled;
      btn.style.opacity = disabled ? '0.6' : '1';
      btn.style.pointerEvents = disabled ? 'none' : 'auto';
    }
  }

  /* Ebooks with a direct PDF on this server get an instant download button.
     Any ebookId not listed here falls back to the "check your email" message
     (handled by the backend email delivery once that's wired up). */
  var EBOOK_PDF_FILES = {
    'high-protein-breakfast': 'ebooks/High-Protein-Breakfast.pdf',
    'gut-health-reset': 'ebooks/Gut-Health-Reset.pdf',
    'power-lunch': 'ebooks/Power-Lunch.pdf',
    'snack-smart': 'ebooks/Snack-Smart.pdf',
    'ancient-grain-modern-plate': 'ebooks/Ancient-Grain-Modern-Plate.pdf',
    'picky-eaters': 'ebooks/Picky-Eaters.pdf'
  };

  function onPaymentDelivered(){
    payStatus.style.display = 'none';
    var dl = document.getElementById('coDownloadBtn');
    var bonus = document.getElementById('coBonusBtn');
    var pdfPath = EBOOK_PDF_FILES[currentEbookId];
    if (pdfPath){
      dl.textContent = 'Download eBook';
      dl.href = pdfPath;
      dl.setAttribute('download', '');
      dl.onclick = null;
    } else {
      dl.textContent = 'Check Your Email 📧';
      dl.removeAttribute('href');
      dl.onclick = function(e){
        e.preventDefault();
        alert('Your eBook has been emailed to ' + currentCustomer.email + '. Please check your inbox (and spam folder) — it may take a minute to arrive.');
      };
    }
    /* Every paid ebook purchase also gets the free Move Well workout guide as a bonus */
    bonus.style.display = 'block';
    showStep(stepSuccess);
  }

  /**
   * Real payment flow:
   * 1) ask our server to create a Razorpay order (server looks up the real price)
   * 2) open Razorpay Checkout with that order
   * 3) on successful payment, send the payment id + signature to our server
   * 4) our server verifies the signature and only then emails the eBook PDF
   */
  window.payNow = function(){
    if (!currentEbookId || !currentCustomer.email){
      showPayError('Something went wrong — please go back and re-enter your details.');
      return;
    }

    setPayButtonDisabled(true);
    showPayStatus('Setting up secure payment...');

fetch(CHECKOUT_API_BASE + '/api/orders', {method: 'POST',
  headers: { 
    'Content-Type': 'application/json' 
  },
  body: JSON.stringify({ 
    ebookId: currentEbookId, 
    customer: currentCustomer,
    amount: Number(currentPrice)
  })
})
.then(function(res){ 
  return res.json().then(function(data){ 
    return { ok: res.ok, data: data }; 
  }); 
})
.then(function(result){
  if (!result.ok) throw new Error(result.data.error || 'Could not start payment.');

  var order = result.data;

  console.log("ORDER RESPONSE:", order);

  var rzp = new Razorpay({
          key: order.keyId,
          amount: order.amount,
          currency: order.currency,
          order_id: order.orderId,
          name: 'KalpAahar',
          description: currentTitle,
          prefill: {
            name: currentCustomer.name,
            email: currentCustomer.email,
            contact: currentCustomer.phone
          },
          theme: { color: '#2E8B57' },
          handler: function(response){
            showPayStatus('Payment received — verifying and sending your eBook...');

            fetch(CHECKOUT_API_BASE + '/api/verify', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                razorpay_order_id: response.razorpay_order_id,
                razorpay_payment_id: response.razorpay_payment_id,
                razorpay_signature: response.razorpay_signature,
                ebookId: currentEbookId,
                customer: currentCustomer
              })
            })
              .then(function(res){ return res.json().then(function(data){ return { ok: res.ok, data: data }; }); })
              .then(function(result){
                setPayButtonDisabled(false);
                if (!result.ok) throw new Error(result.data.error || 'Payment verification failed.');
                onPaymentDelivered();
              })
              .catch(function(err){
                setPayButtonDisabled(false);
                showPayError(
                  'Payment succeeded, but we could not confirm delivery automatically (' +
                  err.message + '). Please contact us with your payment id: ' + response.razorpay_payment_id
                );
              });
          },
          modal: {
            ondismiss: function(){
              setPayButtonDisabled(false);
              payStatus.style.display = 'none';
            }
          }
        });

        rzp.on('payment.failed', function(response){
          setPayButtonDisabled(false);
          showPayError('Payment failed: ' + (response.error && response.error.description ? response.error.description : 'please try again.'));
        });

        payStatus.style.display = 'none';
        rzp.open();
      })
      .catch(function(err){
        setPayButtonDisabled(false);
        showPayError(err.message || 'Could not start payment. Please try again.');
      });
  };
})();

