function openSupportImage(key){
  var data = SUPPORT_IMAGES[key];
  if(!data) return;
  var img = document.getElementById('supportOverlayImg');
  img.src = 'data:image/jpeg;base64,' + data;
  img.alt = key;

  var info = SUPPORT_INFO[key];
  var infoBox = document.getElementById('supportOverlayInfo');
  var contactBtn = '<a href="#contact" class="btn btn-primary" style="margin-top:20px;" onclick="closeSupportImage()">Contact Us</a>';
  if(info){
    var pts = info.points.map(function(p){ return '<li>' + p + '</li>'; }).join('');
    infoBox.innerHTML = '<h3>' + info.title + '</h3>' +
      '<p>' + info.desc + '</p>' +
      '<div class="who-box"><p><strong>Who it&#39;s for:</strong> ' + info.who + '</p></div>' +
      '<p class="includes-label">What this includes</p>' +
      '<ul>' + pts + '</ul>' +
      contactBtn;
  } else {
    infoBox.innerHTML = contactBtn;
  }

  document.getElementById('supportOverlay').classList.add('open');
  document.body.style.overflow = 'hidden';
}
function closeSupportImage(){
  document.getElementById('supportOverlay').classList.remove('open');
  document.body.style.overflow = '';
}
document.addEventListener('keydown', function(e){
  if(e.key === 'Escape') closeSupportImage();
});

